def heuristic_score(G, invariants, conjecture):
    violation = conjecture.violation(invariants)
    return 10.0 * violation + (
        0.5 * ((5 - G.number_of_nodes()) / 5 if G.number_of_nodes() < 5 else 0)
        - 0.2 * min(1, max(0, invariants.get("density", 0) - 0.4))
        - 0.5 * min(1, max(0, (1 - invariants.get("density", 0)) - 0.3))
        if G.number_of_nodes() > 10 else 
        -0.1 * (G.number_of_nodes() / 5)
    )
